def start_withp(words):
    """Write a function to match two words from a list of words starting with letter 'p'."""
    matched = []
    for item in words:
        for word in item.split():
            if word.lower().startswith("p"):
                matched.append(word)
                if len(matched) == 2:
                    return tuple(matched)
    return tuple(matched)
